/// Zero-filled [DATA_BASE, DATA_END) image with every table written at its address.
pub fn image() -> Vec<u8> {
    let mut img = vec![0u8; (DATA_END - DATA_BASE) as usize];
    for e in LAYOUT {
        let b = e.data.bytes();
        let o = (e.va - DATA_BASE) as usize;
        img[o..o + b.len()].copy_from_slice(&b);
    }
    img
}

/// Per-byte flag over [DATA_BASE, DATA_END): true where some table is placed.
pub fn covered() -> Vec<bool> {
    let mut cov = vec![false; (DATA_END - DATA_BASE) as usize];
    for e in LAYOUT {
        let o = (e.va - DATA_BASE) as usize;
        let n = e.data.bytes().len();
        cov[o..o + n].fill(true);
    }
    cov
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn layout_sorted_and_disjoint() {
        let mut end = DATA_BASE;
        for e in LAYOUT {
            assert!(e.va >= end, "{} overlaps", e.name);
            end = e.va + e.data.bytes().len() as u32;
            assert!(end <= DATA_END, "{} past DATA_END", e.name);
        }
    }
}
